/**
 * Drug interaction and contraindication data for oncology products and the co-medications that most often collide
 * with them. Side data; product ids must resolve in the graph (validated by src/lib/interactions.ts) and
 * co-medications are marked `external`. Pairwise flags are derived from the pharmacological properties below
 * (CYP3A4 substrate x strong inhibitor, QT-prolonging x QT-prolonging, acid-dependent absorption x PPI, and so on)
 * by the rule engine in src/lib/interactions.ts; `pairs` records interactions the label calls out by name that the
 * rules would not derive. Every entry cites the US prescribing information (DailyMed) unless stated; CYP
 * classifications follow the FDA drug interaction tables and QT risk follows CredibleMeds where the label is silent.
 */
export type Strength = "strong" | "moderate" | "weak";
export type Severity = "contraindicated" | "major" | "moderate" | "minor";
export type Victim = "cyp3a4Inhibitor" | "cyp3a4Inducer" | "acidReducer" | "qt" | "pgpInhibitor" | "cyp2d6Inhibitor" | "cyp2c8Inhibitor" | "cyp1a2Inhibitor" | "anticoagulant";

export type AgentProps = {
  cyp3a4Substrate?: "sensitive" | "moderate";
  cyp3a4Inhibitor?: Strength;
  cyp3a4Inducer?: Strength;
  cyp2d6Substrate?: boolean;
  cyp2d6Inhibitor?: Strength;
  cyp2c8Substrate?: boolean;
  cyp2c8Inhibitor?: Strength;
  cyp1a2Substrate?: boolean;
  cyp1a2Inhibitor?: Strength;
  /** QT prolongation: "known" = label warning or CredibleMeds known risk; "possible" = conditional or possible risk. */
  qt?: "known" | "possible";
  /** Absorption falls at higher gastric pH. */
  acidDependent?: boolean;
  acidReducer?: "ppi" | "h2" | "antacid";
  pgpSubstrate?: boolean;
  pgpInhibitor?: boolean;
  anticoagulant?: boolean;
  /** Raises bleeding risk with anticoagulants or antiplatelets (e.g. BTK inhibitors, bevacizumab). */
  bleedingRisk?: boolean;
  /** Label names a warfarin interaction (usually INR rise). */
  warfarin?: string;
};

export type ExplicitPair = { with: string; severity: Severity; mechanism: string; management: string; source?: string };

export type Agent = {
  id: string;
  name: string;
  /** Co-medication with no product record in OnCo. */
  external?: boolean;
  class: string;
  props: AgentProps;
  /** What to do when this drug is the victim of the named perpetrator class. */
  management?: Partial<Record<Victim, string>>;
  /** Food effect worth a line on the label. */
  food?: string;
  /** Hepatic impairment guidance from the label. */
  hepatic?: string;
  /** Renal impairment guidance from the label. */
  renal?: string;
  pairs?: ExplicitPair[];
  source: string;
};

const dm = (q: string) => `https://dailymed.nlm.nih.gov/dailymed/search.cfm?labeltype=all&query=${encodeURIComponent(q)}`;
export const SOURCES = {
  fdaCyp: { label: "FDA drug interaction tables (substrates, inhibitors, inducers)", url: "https://www.fda.gov/drugs/drug-interactions-labeling/drug-development-and-drug-interactions-table-substrates-inhibitors-and-inducers" },
  crediblemeds: { label: "CredibleMeds QTdrugs list", url: "https://crediblemeds.org/" },
};

